import shutil,os,json,hashlib,time
SRC='/tmp/opensip-design-corrections/candidate-subject.v25'
BASE='/private/tmp/opensip-design-corrections/claude-discovery-correction.v1/scratch'
DST=BASE+'/successor'
for d in [BASE+'/output',BASE+'/probes',BASE+'/work']: os.makedirs(d,exist_ok=True)
if os.path.exists(DST): shutil.rmtree(DST)
t0=time.time()
def ig(d,names):
    if os.path.abspath(d)==os.path.abspath(os.path.join(SRC,'docs/coop/design-corrections')):
        return {'reviews'}
    return set()
shutil.copytree(SRC,DST,ignore=ig)
# restore the six pinned files the source-pin ledgers reference
need=[]
for rel in ['docs/coop/design-corrections/security/source-pins.v1.json','docs/coop/design-corrections/native/source-pins.v2.json']:
    d=json.load(open(os.path.join(DST,rel)))
    for row in d['pins']:
        if not os.path.exists(os.path.join(DST,row['path'])): need.append(row['path'])
for p in sorted(set(need)):
    s=os.path.join(SRC,p); t=os.path.join(DST,p)
    os.makedirs(os.path.dirname(t),exist_ok=True); shutil.copy2(s,t)
n=sum(len(f) for _,_,f in os.walk(DST))
print('copied files',n,'restored pinned',len(set(need)),'in %.1fs'%(time.time()-t0))
for rel in ['docs/coop/design-corrections/discovery-defaults.py','docs/coop/design-corrections/security/security_lifecycle_model_v1.py','docs/coop/design-corrections/native/native_evidence_model.v2.py']:
    a=hashlib.sha256(open(os.path.join(SRC,rel),'rb').read()).hexdigest()
    b=hashlib.sha256(open(os.path.join(DST,rel),'rb').read()).hexdigest()
    print(rel.split('/')[-1], a==b, a[:16])
"
